import { serve } from 'https://deno.land/std@0.190.0/http/server.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.50.3'
import { getCorsHeaders } from '../_shared/cors.ts'

/**
 * Remet le référentiel OIC et les titres des 367 items conformes à UNESS.
 *
 * POURQUOI
 * --------
 * Comparaison ligne à ligne, le 18/09/2026, entre la table Cargo officielle
 * `Objectif_de_connaissance` de livret.uness.fr/lisa/2026 et la base :
 *   identifiants présents ....... 4872 / 4872  (0 manquant, 0 en trop, 0 doublon)
 *   rang correct ................ 4872 / 4872
 *   item parent correct ......... 4872 / 4872
 *   INTITULÉ DIFFÉRENT .......... 2942 / 4872  (60 %)
 *   RUBRIQUE DIFFÉRENTE ......... 4872 / 4872  (100 %)
 * Les intitulés étaient tronqués (« pratique médicale » au lieu de « Connaître
 * la définition de la pratique médicale et connaitre la signification de
 * l'éthique ») et la rubrique avait été attribuée par POSITION : « Génétique »
 * revenait exactement 367 fois, une par item.
 * Côté items : 27 titres désignaient un autre item que celui du référentiel,
 * 30 étaient tronqués.
 *
 * CE QU'ELLE FAIT
 * ---------------
 * - action « verifier » (défaut) : ne touche à rien, renvoie l'écart mesuré.
 * - action « appliquer » : réécrit intitulé, rubrique et ordre des 4872
 *   objectifs, les titres des 367 items, et vide les colonnes de remplissage
 *   fabriquées par génération automatique (sommaire, mécanismes, indications…
 *   une même phrase y revient jusqu'à 569 fois sur 1000 lignes).
 *
 * Elle ne supprime aucune ligne. Elle ne touche ni `description`, ni
 * `url_source`, ni les 734 lignes IC-<n> (le front ne les affiche plus).
 * Idempotente : relancée, elle ne réécrit que ce qui diffère encore.
 *
 * Les données officielles sont embarquées ici (gzip + base64) pour que la
 * correction soit reproductible sans accès à UNESS.
 *
 * FONCTION À USAGE UNIQUE. Elle est déclarée sans vérification de jeton pour
 * pouvoir être déclenchée une fois ; elle ne sait rien faire d'autre que
 * réécrire les valeurs officielles embarquées, donc un appel non désiré ne
 * peut que remettre la base en conformité. Elle DOIT être supprimée du dépôt
 * dès que le rapport indique « conforme: true ».
 */

const DONNEES_B64 = ''


const EST_COMPETENCE_REELLE = /^OIC-\d{3}-\d{2}-[AB]$/

interface Officiel { objectif_id: string; intitule: string; rubrique: string; ordre: number | null }

async function chargerOfficiel(): Promise<{ competences: Officiel[]; items: { item_code: string; title: string }[] }> {
  const binaire = Uint8Array.from(atob(DONNEES_B64), (c) => c.charCodeAt(0))
  const flux = new Blob([binaire]).stream().pipeThrough(new DecompressionStream('gzip'))
  const texte = await new Response(flux).text()
  const [blocComp, blocItems] = texte.split('\n@@ITEMS@@\n')

  const competences: Officiel[] = blocComp.split('\n').filter(Boolean).map((l) => {
    const [objectif_id, intitule, rubrique, ordre] = l.split('\t')
    const n = parseInt(ordre ?? '', 10)
    return { objectif_id, intitule, rubrique: rubrique ?? '', ordre: Number.isFinite(n) ? n : null }
  })

  const items = (blocItems ?? '').split('\n').filter(Boolean).map((l) => {
    const [item_code, title] = l.split('\t')
    return { item_code, title }
  })

  return { competences, items }
}

const COLONNES_DE_REMPLISSAGE = [
  'sommaire', 'mecanismes', 'indications', 'effets_indesirables',
  'interactions', 'modalites_surveillance', 'causes_echec',
  'contributeurs', 'titre_complet',
]

serve(async (req) => {
  const corsHeaders = getCorsHeaders(req)
  if (req.method === 'OPTIONS') return new Response(null, { headers: corsHeaders })

  const repondre = (corps: unknown, status = 200) =>
    new Response(JSON.stringify(corps, null, 2), {
      status, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    })

  try {
    const { action = 'verifier' } = await req.json().catch(() => ({}))
    if (!['verifier', 'appliquer'].includes(action)) {
      return repondre({ error: "action doit valoir « verifier » ou « appliquer »" }, 400)
    }

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,
    )

    const { competences: officiel, items: itemsOfficiels } = await chargerOfficiel()
    if (officiel.length !== 4872 || itemsOfficiels.length !== 367) {
      return repondre({ error: `données embarquées incohérentes : ${officiel.length} compétences, ${itemsOfficiels.length} items` }, 500)
    }

    // --- état actuel -------------------------------------------------------
    const actuelles = new Map<string, { intitule: string; rubrique: string; ordre: number | null }>()
    for (let debut = 0; debut < 8000; debut += 1000) {
      const { data, error } = await supabase
        .from('oic_competences')
        .select('objectif_id, intitule, rubrique, ordre')
        .order('objectif_id')
        .range(debut, debut + 999)
      if (error) return repondre({ error: `lecture oic_competences : ${error.message}` }, 500)
      if (!data || data.length === 0) break
      for (const r of data) {
        if (EST_COMPETENCE_REELLE.test(r.objectif_id)) {
          actuelles.set(r.objectif_id, { intitule: r.intitule, rubrique: r.rubrique, ordre: r.ordre })
        }
      }
      if (data.length < 1000) break
    }

    const aCorriger = officiel.filter((o) => {
      const a = actuelles.get(o.objectif_id)
      if (!a) return false // identifiant absent : on ne crée rien ici
      return a.intitule !== o.intitule || a.rubrique !== o.rubrique || (o.ordre !== null && a.ordre !== o.ordre)
    })
    const absents = officiel.filter((o) => !actuelles.has(o.objectif_id)).map((o) => o.objectif_id)

    const { data: itemsBase, error: eItems } = await supabase
      .from('edn_items_complete')
      .select('item_code, title')
      .limit(400)
    if (eItems) return repondre({ error: `lecture edn_items_complete : ${eItems.message}` }, 500)
    const titresActuels = new Map((itemsBase ?? []).map((i) => [i.item_code, i.title]))
    const titresACorriger = itemsOfficiels.filter((i) => titresActuels.has(i.item_code) && titresActuels.get(i.item_code) !== i.title)

    if (action === 'verifier') {
      return repondre({
        action: 'verifier',
        competences_officielles: officiel.length,
        competences_en_base: actuelles.size,
        competences_a_corriger: aCorriger.length,
        identifiants_absents_en_base: absents.length,
        titres_items_a_corriger: titresACorriger.length,
        exemples: aCorriger.slice(0, 5).map((o) => ({
          objectif_id: o.objectif_id,
          base: actuelles.get(o.objectif_id)?.intitule,
          uness: o.intitule,
        })),
      })
    }

    // --- application -------------------------------------------------------
    // Une requête par objectif, mais 24 en parallèle : en série, les 4872 mises
    // à jour dépassaient la limite de 150 s de la fonction.
    let corrigees = 0
    const echecs: { objectif_id: string; erreur: string }[] = []
    const LARGEUR = 24
    const horodatage = new Date().toISOString()

    const corrigerUn = async (o: Officiel) => {
      const maj: Record<string, unknown> = {
        intitule: o.intitule,
        rubrique: o.rubrique,
        updated_at: horodatage,
      }
      if (o.ordre !== null) maj.ordre = o.ordre
      const { error } = await supabase.from('oic_competences').update(maj).eq('objectif_id', o.objectif_id)
      if (error) { if (echecs.length < 20) echecs.push({ objectif_id: o.objectif_id, erreur: error.message }) }
      else corrigees++
    }

    for (let i = 0; i < aCorriger.length; i += LARGEUR) {
      await Promise.all(aCorriger.slice(i, i + LARGEUR).map(corrigerUn))
    }

    let titresCorriges = 0
    for (let i = 0; i < titresACorriger.length; i += LARGEUR) {
      await Promise.all(titresACorriger.slice(i, i + LARGEUR).map(async (it) => {
        const { error } = await supabase
          .from('edn_items_complete')
          .update({ title: it.title, updated_at: horodatage })
          .eq('item_code', it.item_code)
        if (!error) titresCorriges++
        else if (echecs.length < 20) echecs.push({ objectif_id: it.item_code, erreur: error.message })
        await supabase.from('edn_items_immersive').update({ title: it.title }).eq('item_code', it.item_code)
      }))
    }

    // Colonnes de remplissage : vidées par lots de 500 identifiants.
    const vide: Record<string, null> = {}
    for (const c of COLONNES_DE_REMPLISSAGE) vide[c] = null
    let remplissageVide = 0
    const ids = officiel.map((o) => o.objectif_id)
    for (let i = 0; i < ids.length; i += 500) {
      const lot = ids.slice(i, i + 500)
      const { error } = await supabase.from('oic_competences').update(vide).in('objectif_id', lot)
      if (!error) remplissageVide += lot.length
    }

    // --- contrôle ----------------------------------------------------------
    const apres = new Map<string, string>()
    for (let debut = 0; debut < 8000; debut += 1000) {
      const { data } = await supabase
        .from('oic_competences')
        .select('objectif_id, intitule')
        .order('objectif_id')
        .range(debut, debut + 999)
      if (!data || data.length === 0) break
      for (const r of data) if (EST_COMPETENCE_REELLE.test(r.objectif_id)) apres.set(r.objectif_id, r.intitule)
      if (data.length < 1000) break
    }
    const restants = officiel.filter((o) => apres.has(o.objectif_id) && apres.get(o.objectif_id) !== o.intitule)

    return repondre({
      action: 'appliquer',
      competences_corrigees: corrigees,
      titres_items_corriges: titresCorriges,
      colonnes_de_remplissage_videes: remplissageVide,
      identifiants_absents_en_base: absents.length,
      echecs: echecs.length,
      detail_echecs: echecs,
      intitules_encore_differents: restants.length,
      conforme: restants.length === 0 && echecs.length === 0,
    })
  } catch (e) {
    const message = e instanceof Error ? e.message : String(e)
    console.error('referentiel-uness-2026 :', message)
    return repondre({ error: message }, 500)
  }
})
